101	Future<void> _fetchForCriteria(Emitter<RecordsState> emit) async {
102	  final generation = ++_fetchGeneration;
103	  final current = state;
104	  if (current is RecordsLoaded) {
105	    emit(current.copyWith(
106	      isApplyingCriteria: true,
107	      searchQuery: _query, dateRange: _dateRange, entryTypes: _entryTypes,
108	    ));
109	  }
110	  // Nothing to show yet (still on RecordsLoading/RecordsLoadFailure) — RecordsStarted's own
111	  // _loadFirstPage() owns the very first fetch; this path is only reachable once a RecordsLoaded exists.
112	
113	  final now = DateTime.now();
114	  final bounds = _dateRange.boundsAt(now);
115	  final result = await _resolveEntries(
116	    query: _query, dateFrom: bounds.from, dateTo: bounds.to, types: _entryTypes,
117	  );
118	  if (generation != _fetchGeneration) return;   // superseded — discard silently (FR-005a)
119	
120	  result.match(
121	    (failure) {
122	      if (failure is AuthExpiredFailure) _reauthController.add(null);
123	      final latest = state;
124	      if (latest is RecordsLoaded) {
125	        emit(latest.copyWith(isApplyingCriteria: false, criteriaLoadFailure: failure));
126	      }
127	    },
128	    (fetched) {
129	      final latest = state;
130	      if (latest is! RecordsLoaded) return;
131	      emit(latest.copyWith(
132	        entries: fetched.entries,
133	        nextCursor: fetched.nextCursor,          // null whenever bounded (R1)
134	        isApplyingCriteria: false,
135	        criteriaLoadFailure: null,
136	      ));
137	    },
138	  );
139	}
140	
141	/// Picks the shape (single call+cursor vs. bounded fan-out-and-merge) per research.md R1.
142	Future<Either<Failure, ({List<Entry> entries, String? nextCursor})>> _resolveEntries({
143	  required String query,
144	  required DateTime? dateFrom,
145	  required DateTime? dateTo,
146	  required Set<EntrySource> types,
147	}) async {
148	  if (types.length <= 1) {
149	    final source = types.isEmpty ? null : types.single;
150	    if (query.isNotEmpty) {
151	      final result = await _entriesRepository.search(
152	        q: query, source: source, dateFrom: dateFrom, dateTo: dateTo,
153	      );
154	      return result.map((entries) => (entries: entries, nextCursor: null));
155	    }
156	    final result = await _entriesRepository.list(source: source, dateFrom: dateFrom, dateTo: dateTo);
157	    return result.map((page) => (entries: page.entries, nextCursor: page.nextCursor));
158	  }
159	
160	  // 2+ entry types — bounded fan-out, one call per type (research.md R1).
161	  final calls = types.map(
162	    (source) => query.isNotEmpty
163	        ? _entriesRepository.search(q: query, source: source, dateFrom: dateFrom, dateTo: dateTo)
164	        : _entriesRepository.list(source: source, dateFrom: dateFrom, dateTo: dateTo, limit: 50)
165	            .then((r) => r.map((page) => page.entries)),
166	  );
167	  final results = await Future.wait(calls);
168	  for (final r in results) {
169	    if (r.isLeft()) return r.map((_) => (entries: <Entry>[], nextCursor: null));   // first failure wins
170	  }
171	  final merged = EntryMerger.mergeMany(
172	    sources: [for (final r in results) r.getOrElse((_) => [])],
173	    byRelevance: query.isNotEmpty,
174	  );
175	  return Right((entries: merged, nextCursor: null));
176	}
177	```
178	
179	- Changing criteria always restarts from "page 1" — `_resolveEntries` never threads an old `cursor` through;
180	  the previous `nextCursor` is discarded the moment any criteria-changing event fires.
181	- `RecordsLoaded.copyWith(...)` is the one new convenience method added to `RecordsLoaded` purely to keep
182	  these handlers from re-listing every unrelated field on every emit (standard Dart data-class ergonomics,
183	  not a new domain concept).
