[{"id": "...", "title": "...", "personaSnapshot": "analitico", "userMessageCount": 3,
  "lastUserMessageAt": "2026-10-19T12:00:00.000Z", "createdAt": "...", "updatedAt": "..."}, ...]

// key: chatMessagesLocalCache
{"<sessionId>": [{"id": "...", "sessionId": "...", "role": "user", "content": "...",
